    """Serializable fields retain statement order, decorators and multiplicity."""

    def fields(value: Any) -> Any:
        if isinstance(value, ast.AST):
            return {
                "_type": type(value).__name__,
                **{k: fields(v) for k, v in ast.iter_fields(value)},
            }
